// TH16 v1.00a Stage 2 BossCard2 spell 12 "刃符「山姥の包丁研ぎ」".
// Source: st02bs.ecl.txt:453-547 (BossCard2 entry) + :549-580 (BossCard2_at).

const TIME_LIMIT: int = 1924;      // 120 shell buffer + 1800 setInterrupt + 4 startup
const OPENING_BUFFER: int = 120;

const TH16_RICE: int = 480;        // source etSprite(0, 8, 13): type 8 = rice
const KNIFE_COLOR: int = 13;

// BossCard2_at EX chain (config-time): ANIM(1) / REACT(0) / BRIGHT(1) /
// WAIT(30 + RAND%90) / VELTIME(a=60, r=1.8, s=RANDRAD).  ANIM animation, REACT and
// BRIGHT are presentation-only; the ANIM birth step (position -= 4*velocity = 2.4px
// up along the 90deg spawn velocity) stays and is applied at the fire position.
// Both random values are read by the source at etExSet time, i.e. once per shot.
xformdef KNIFE(hold: int, dir: angle) {
    wait(hold);
    set_gravity(0.02fx * cos(dir), 0.02fx * sin(dir));   // (1.8 - 0.6) / 60 per frame
    wait(60);
    set_gravity(0fx, 0fx);
}

// ---- moveRand(60, 4, 3.0) under moveLimit(0, 128, 240, 64) -------------------
// Verified TH16 movement recipe (movement.md), reused with this card's speed and
// limit: per-step speed 3*(60-k)/60, clamp x in [-120,120], y in [96,160], direction
// interior x +-60 / y 112..144.  Enemy int slot 0 = next step count, fx slots 0/1 =
// logical unit vector; this attack uses no other I/F slot.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 3fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

sub card_move_rand() {
    // Source signed unit random * pi, held as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// ---- BossCard2_at -----------------------------------------------------------
// etNew(0); etAim(0,3) fixed 1-way ring; etSprite rice/13; etAngle 90deg;
// etSpeed 0.6 (layers=1, so s1 unused); etOffsetRad(0, 0, A) -> offset (A, 0).
sub knife_shot(offset: fx) {
    var hold: int = 30 + rand(90);                      // WAIT a = 30 + RAND%90
    var dir: angle = (rand(65536) - 32768) as angle;    // VELTIME s = RANDRAD
    _ = fire(TH16_RICE, KNIFE_COLOR,
             $self_x + offset, $self_y - 2.4fx,
             0.6fx, 90deg, KNIFE(hold, dir), none);
}

// diffI(C,13,25,25,25) outer rounds; each round fires 3 shots then wait(1).
sub knife_wave(start: fx, step: fx, count: int) {
    var a: fx = start;
    for i in 0..count {
        for d in 0..3 {
            knife_shot(a);
            a = a + step;
        }
        wait(1);
    }
}

// ---- card body --------------------------------------------------------------
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);        // setHitbox(48, 48): circle radius 48/2
    set_hurtbox(20fx);       // setHurtbox(40, 40): 40/2
    // movePosTime(60, 4, 0, 128) after the entry zero-velocity reset; entry is
    // already (0, 128), so this move has no displacement.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    var t0: int = $frame;
    wait(90);                // source +90 gate before the first wave

    var count: int = 25;     // diffI(C, 13, 25, 25, 25)
    if global(GVAR_RANK) == RANK_EASY { count = 13; }
    var rounds: int = 2;     // $DIFF <= 1
    var gap: int = 60;
    if global(GVAR_RANK) == RANK_HARD { rounds = 3; gap = 40; }     // $DIFF <= 2
    if global(GVAR_RANK) == RANK_LUNATIC { rounds = 4; gap = 30; }

    // $B = 1000 is effectively unbounded; the 1800-frame interrupt ends the card.
    loop {
        var side: fx = -60fx;
        var step: fx = 3fx;
        for r in 0..rounds {
            if $frame - t0 >= 1800 { return; }
            knife_wave(side, step, count);
            wait(gap);
            side = 0fx - side;
            step = 0fx - step;
        }
        if $frame - t0 >= 1800 { return; }
        card_move_rand();     // BossCard2_2236
        card_wait(70);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2200, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
